def news(q, limit=None, cursor=None, sort=None, language=None, region=None, time_range=None, **_extra):
    import json, os, datetime, time, base64, hashlib, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0094000" if __import__("os").path.isdir("./environment_mix/0094000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{hashlib.sha256((now + '|' + os.urandom(8).hex()).encode()).hexdigest()[:24]}"

    def _month_start_iso(dt):
        d = dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        return d.isoformat() + "Z"

    def _parse_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or not cur:
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict): return None
            if obj.get("v") != 1: return None
            if obj.get("tool") != "news": return None
            off = obj.get("offset")
            if not isinstance(off, int) or off < 0: return None
            return off
        except Exception:
            return None

    def _make_cursor(off):
        obj = {"v": 1, "tool": "news", "offset": off}
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # validate
    if not isinstance(q, str) or not q.strip():
        return _err("VALIDATION_ERROR", "q must be a non-empty string")
    if limit is None:
        limit_i = 10
    else:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit < 1 or limit > 50:
            return _err("VALIDATION_ERROR", "limit must be between 1 and 50")
        limit_i = limit
    if sort is not None and sort not in ("relevance", "date"):
        return _err("VALIDATION_ERROR", "sort must be one of: relevance, date")
    if time_range is not None and time_range not in ("day", "week", "month", "year", "all"):
        return _err("VALIDATION_ERROR", "time_range must be one of: day, week, month, year, all")
    if language is not None and (not isinstance(language, str) or not language.strip()):
        return _err("VALIDATION_ERROR", "language must be a non-empty string when provided")
    if region is not None and (not isinstance(region, str) or not region.strip()):
        return _err("VALIDATION_ERROR", "region must be a non-empty string when provided")
    offset = _parse_cursor(cursor)
    if offset is None:
        return _err("VALIDATION_ERROR", "cursor is malformed")

    clients = _load("api_clients.json")
    keys = _load("api_keys.json")
    reqs = _load("tool_requests.json")

    active_clients = [c for c in clients if c.get("status") == "active" and isinstance(c.get("id"), str)]
    active_keys = [k for k in keys if k.get("status") == "active" and isinstance(k.get("client_id"), str)]

    def _count_month_requests(client_id):
        month_start = _month_start_iso(datetime.datetime.utcnow())
        return sum(1 for r in reqs if r.get("client_id") == client_id and isinstance(r.get("created_at"), str) and r["created_at"] >= month_start)

    chosen = None
    for c in active_clients:
        cid = c["id"]
        ckeys = [k for k in active_keys if k.get("client_id") == cid]
        if not ckeys:
            continue
        lim = c.get("monthly_request_limit")
        if not isinstance(lim, int) or lim < 0:
            continue
        if _count_month_requests(cid) < lim:
            chosen = (c, ckeys[0])
            break

    if chosen is None:
        any_client = None
        any_key = None
        for c in clients:
            if isinstance(c.get("id"), str):
                any_client = c
                break
        if any_client:
            for k in keys:
                if k.get("client_id") == any_client.get("id"):
                    any_key = k
                    break
            tr_id = _new_id("tr")
            tr = {
                "id": tr_id,
                "client_id": any_client["id"],
                "api_key_id": any_key.get("id") if isinstance(any_key, dict) else None,
                "tool_name": "news",
                "status": "throttled",
                "request_payload": {"q": q, "limit": limit, "cursor": cursor, "sort": sort, "language": language, "region": region, "time_range": time_range},
                "response_payload": None,
                "http_status": 429,
                "error_code": "RATE_LIMIT",
                "error_message": "Request throttled (inactive credentials or monthly request limit exceeded).",
                "ip_address": None,
                "user_agent": None,
                "latency_ms": None,
                "compute_units": 1,
                "created_at": now,
                "updated_at": now
            }
            tr["response_payload"] = _err("RATE_LIMIT", tr["error_message"])
            reqs.append(tr)
            _save("tool_requests.json", reqs)
            return tr["response_payload"]
        return _err("UNAUTHORIZED", "No active client and API key combination available to serve this request")

    client, api_key = chosen
    client_id = client["id"]
    api_key_id = api_key["id"]

    tr_id = _new_id("tr")
    request_payload = {"q": q, "limit": limit, "cursor": cursor, "sort": sort, "language": language, "region": region, "time_range": time_range}
    tr = {
        "id": tr_id,
        "client_id": client_id,
        "api_key_id": api_key_id,
        "tool_name": "news",
        "status": "received",
        "request_payload": request_payload,
        "response_payload": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "ip_address": None,
        "user_agent": None,
        "latency_ms": None,
        "compute_units": 1,
        "created_at": now,
        "updated_at": now
    }
    reqs.append(tr)
    _save("tool_requests.json", reqs)

    if client.get("status") != "active" or api_key.get("status") != "active":
        tr["status"] = "throttled"
        tr["http_status"] = 401
        tr["error_code"] = "UNAUTHORIZED"
        tr["error_message"] = "Client or API key is not active."
        tr["updated_at"] = now
        tr["response_payload"] = _err("UNAUTHORIZED", tr["error_message"])
        tr["latency_ms"] = int((time.time() - t0) * 1000)
        for i in range(len(reqs) - 1, -1, -1):
            if reqs[i].get("id") == tr_id:
                reqs[i] = tr
                break
        _save("tool_requests.json", reqs)
        return tr["response_payload"]

    month_used = sum(1 for r in reqs if r.get("client_id") == client_id and isinstance(r.get("created_at"), str) and r["created_at"] >= _month_start_iso(datetime.datetime.utcnow()))
    if isinstance(client.get("monthly_request_limit"), int) and month_used > client["monthly_request_limit"]:
        tr["status"] = "throttled"
        tr["http_status"] = 429
        tr["error_code"] = "RATE_LIMIT"
        tr["error_message"] = "Monthly request limit exceeded."
        tr["updated_at"] = now
        tr["response_payload"] = _err("RATE_LIMIT", tr["error_message"])
        tr["latency_ms"] = int((time.time() - t0) * 1000)
        for i in range(len(reqs) - 1, -1, -1):
            if reqs[i].get("id") == tr_id:
                reqs[i] = tr
                break
        _save("tool_requests.json", reqs)
        return tr["response_payload"]

    tr["status"] = "running"
    tr["updated_at"] = now
    for i in range(len(reqs) - 1, -1, -1):
        if reqs[i].get("id") == tr_id:
            reqs[i] = tr
            break
    _save("tool_requests.json", reqs)

    try:
        qn = re.sub(r"\s+", " ", q.strip())
        seed = hashlib.sha256((qn + "|" + (language or "") + "|" + (region or "") + "|" + (time_range or "")).encode("utf-8")).hexdigest()
        total = 150
        start = offset
        end = min(offset + limit_i, total)

        # time_range affects published_at distribution
        def _published_at(i):
            # deterministic timestamps in the past
            delta_days = (int(seed[i % len(seed)], 16) % 365)
            if time_range == "day":
                delta_days = delta_days % 1
            elif time_range == "week":
                delta_days = delta_days % 7
            elif time_range == "month":
                delta_days = delta_days % 31
            elif time_range == "year":
                delta_days = delta_days % 365
            else:
                delta_days = delta_days % 365
            dt = now_dt - datetime.timedelta(days=delta_days, hours=(i % 24), minutes=(i * 7) % 60)
            return dt.replace(microsecond=0).isoformat() + "Z"

        articles = []
        for i in range(start, end):
            h = hashlib.sha256((seed + f"|{i}").encode("utf-8")).hexdigest()
            outlet = f"news{int(h[:2], 16) % 30}.example"
            url = f"https://{outlet}/article/{h[2:12]}"
            articles.append({
                "title": f"{qn} — Article {i+1}",
                "url": url,
                "source": outlet,
                "snippet": f"Generated news match for '{qn}'. Ref: {h[12:24]}",
                "published_at": _published_at(i)
            })

        if sort == "date":
            # already monotonic-ish, but sort by published_at desc
            articles.sort(key=lambda a: a.get("published_at") or "", reverse=True)

        has_more = end < total
        next_cursor = _make_cursor(end) if has_more else None
        response = {
            "articles": articles,
            "meta": {
                "query": qn,
                "limit": limit_i,
                "cursor": cursor,
                "next_cursor": next_cursor,
                "total": total,
                "has_more": has_more,
                "sort": sort or "relevance",
                "language": language,
                "region": region,
                "time_range": time_range or "all"
            }
        }

        for k in keys:
            if k.get("id") == api_key_id:
                k["last_used_at"] = now
                k["updated_at"] = now
                break
        _save("api_keys.json", keys)

        tr["status"] = "succeeded"
        tr["http_status"] = 200
        tr["response_payload"] = response
        tr["latency_ms"] = int((time.time() - t0) * 1000)
        tr["updated_at"] = now
        for i in range(len(reqs) - 1, -1, -1):
            if reqs[i].get("id") == tr_id:
                reqs[i] = tr
                break
        _save("tool_requests.json", reqs)
        return response
    except Exception as e:
        tr["status"] = "failed"
        tr["http_status"] = 500
        tr["error_code"] = "FAILED"
        tr["error_message"] = f"Internal error: {type(e).__name__}"
        tr["response_payload"] = _err("CONFLICT", tr["error_message"])
        tr["latency_ms"] = int((time.time() - t0) * 1000)
        tr["updated_at"] = now
        for i in range(len(reqs) - 1, -1, -1):
            if reqs[i].get("id") == tr_id:
                reqs[i] = tr
                break
        _save("tool_requests.json", reqs)
        return tr["response_payload"]

def sitemap(url, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, hashlib
    from urllib.parse import urlsplit, urlunsplit

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0094000" if __import__("os").path.isdir("./environment_mix/0094000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    def _gen_id(prefix, existing_ids):
        import secrets
        while True:
            cand = f"{prefix}_{secrets.token_hex(12)}"
            if cand not in existing_ids:
                return cand

    def _normalize_url(u):
        if not isinstance(u, str) or not u.strip():
            return None
        try:
            sp = urlsplit(u.strip())
        except Exception:
            return None
        if sp.scheme.lower() not in ("http", "https"):
            return None
        if not sp.netloc:
            return None
        host = (sp.hostname or "").lower()
        if not host:
            return None
        port = sp.port
        default_port = 80 if sp.scheme.lower() == "http" else 443
        netloc = host
        if port and port != default_port:
            netloc = f"{host}:{port}"
        path = sp.path or "/"
        # drop fragment always; keep query
        return urlunsplit((sp.scheme.lower(), netloc, path, sp.query or "", ""))

    def _url_hash(norm):
        return hashlib.sha256(norm.encode("utf-8")).hexdigest()

    def _month_window(dt):
        start = dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        # next month:
        if start.month == 12:
            end = start.replace(year=start.year + 1, month=1)
        else:
            end = start.replace(month=start.month + 1)
        return start, end

    def _cursor_decode(cur):
        if cur is None:
            return {"offset": 0, "seed_hash": None}
        if not isinstance(cur, str) or not cur:
            return None
        # Be permissive: accept raw JSON as well as base64url JSON.
        obj = None
        if cur.lstrip().startswith("{") and cur.rstrip().endswith("}"):
            try:
                obj = json.loads(cur)
            except Exception:
                obj = None
        if obj is None:
            try:
                pad = "=" * (-len(cur) % 4)
                raw = base64.urlsafe_b64decode((cur + pad).encode("utf-8"))
                obj = json.loads(raw.decode("utf-8"))
            except Exception:
                return None
        if not isinstance(obj, dict):
            return None
        off = obj.get("offset", 0)
        seed = obj.get("seed_hash")
        if not isinstance(off, int) or off < 0:
            return None
        if seed is not None and (not isinstance(seed, str) or len(seed) < 16):
            return None
        return {"offset": off, "seed_hash": seed}

    def _cursor_encode(offset, seed_hash):
        obj = {"v": 1, "tool": "sitemap", "offset": int(offset), "seed_hash": seed_hash}
        raw = json.dumps(obj, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # Validate inputs (schema-level)
    if url is None or not isinstance(url, str) or not url.strip():
        return _err("VALIDATION_ERROR", "url is required and must be a non-empty string.")
    if limit is None:
        limit = 10
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer.")
    if limit < 1 or limit > 100:
        return _err("VALIDATION_ERROR", "limit out of range; must be between 1 and 100.")
    cinfo = _cursor_decode(cursor)
    if cinfo is None:
        return _err("VALIDATION_ERROR", "cursor is malformed.")

    # Resolve an authenticated/usable context (ambient auth): choose any active api_key + active client.
    clients = _load("api_clients.json")
    keys = _load("api_keys.json")
    tool_requests = _load("tool_requests.json")
    sitemaps = _load("sitemaps.json")

    clients_by_id = {c.get("id"): c for c in clients if isinstance(c, dict) and isinstance(c.get("id"), str)}
    active_key_rows = []
    now_dt = datetime.datetime.now(datetime.timezone.utc)

    for k in keys:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        cid = k.get("client_id")
        c = clients_by_id.get(cid)
        if not c or c.get("status") != "active":
            continue
        exp = _parse_rfc3339(k.get("expires_at"))
        if exp is not None and exp.tzinfo is None:
            exp = exp.replace(tzinfo=datetime.timezone.utc)
        if exp is not None and exp <= now_dt:
            continue
        active_key_rows.append((c, k))

    if not active_key_rows:
        # No working combination exists in datastore
        return _err("UNAUTHORIZED", "No active client/api key context available to serve this request.")

    # Use the first viable combination (must exist per above); this is the ambient auth resolution.
    client_row, key_row = active_key_rows[0]
    client_id = client_row["id"]
    api_key_id = key_row["id"]

    # Create exactly one tool_requests row for this invocation
    existing_ids = {r.get("id") for r in tool_requests if isinstance(r, dict)}
    req_id = _gen_id("s1r", existing_ids)
    now = _now_iso()
    tr = {
        "id": req_id,
        "client_id": client_id,
        "api_key_id": api_key_id,
        "tool_name": "sitemap",
        "status": "received",
        "request_payload": {"url": url, "limit": limit, "cursor": cursor},
        "response_payload": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "ip_address": None,
        "user_agent": None,
        "latency_ms": None,
        "compute_units": 1,
        "created_at": now,
        "updated_at": now,
    }
    tool_requests.append(tr)
    _save("tool_requests.json", tool_requests)

    def _update_tr(status, http_status=None, response_payload=None, error_code=None, error_message=None, latency_ms=None):
        trs = _load("tool_requests.json")
        now2 = _now_iso()
        for r in trs:
            if isinstance(r, dict) and r.get("id") == req_id:
                # enforce response_payload null for received/running
                r["status"] = status
                r["http_status"] = http_status
                r["error_code"] = error_code
                r["error_message"] = error_message
                r["latency_ms"] = latency_ms
                if status in ("received", "running"):
                    r["response_payload"] = None
                else:
                    r["response_payload"] = response_payload if response_payload is not None else {}
                r["updated_at"] = now2
                _save("tool_requests.json", trs)
                return

    # Throttle if client/key not active (shouldn't happen due to selection) or quotas exceeded
    # monthly_request_limit: count all tool_requests for client in current calendar month
    mstart, mend = _month_window(now_dt)

    def _in_month(r):
        dt = _parse_rfc3339(r.get("created_at"))
        if dt is None:
            return False
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return (dt >= mstart) and (dt < mend)

    month_reqs = [r for r in tool_requests if isinstance(r, dict) and r.get("client_id") == client_id and _in_month(r)]
    monthly_request_limit = client_row.get("monthly_request_limit")
    if not isinstance(monthly_request_limit, int) or monthly_request_limit < 0:
        monthly_request_limit = 0

    if len(month_reqs) >= monthly_request_limit:
        payload = _err("QUOTA_EXCEEDED", "Client exceeded monthly_request_limit; request throttled.", limit=monthly_request_limit)
        _update_tr(
            "throttled",
            http_status=429,
            response_payload=payload,
            error_code="RATE_LIMITED",
            error_message="Client exceeded monthly_request_limit; request throttled.",
            latency_ms=int((time.time() - t0) * 1000),
        )
        return payload

    # monthly_crawl_limit: count tool_requests for crawl/sitemap with succeeded/failed
    crawl_limit = client_row.get("monthly_crawl_limit")
    if not isinstance(crawl_limit, int) or crawl_limit < 0:
        crawl_limit = 0
    crawl_like = [
        r for r in tool_requests
        if isinstance(r, dict)
        and r.get("client_id") == client_id
        and _in_month(r)
        and r.get("tool_name") in ("crawl", "sitemap")
        and r.get("status") in ("succeeded", "failed")
    ]
    if len(crawl_like) >= crawl_limit:
        payload = _err("QUOTA_EXCEEDED", "Client exceeded monthly_crawl_limit; request throttled.", limit=crawl_limit)
        _update_tr(
            "throttled",
            http_status=429,
            response_payload=payload,
            error_code="CRAWL_QUOTA_EXCEEDED",
            error_message="Client exceeded monthly_crawl_limit; request throttled.",
            latency_ms=int((time.time() - t0) * 1000),
        )
        return payload

    # Move to running
    _update_tr("running", http_status=202, latency_ms=None)

    norm = _normalize_url(url)
    if norm is None:
        payload = _err("VALIDATION_ERROR", "url is invalid; must be an http(s) URL with a host.")
        _update_tr(
            "failed",
            http_status=400,
            response_payload=payload,
            error_code="VALIDATION_ERROR",
            error_message="url is invalid; must be an http(s) URL with a host.",
            latency_ms=int((time.time() - t0) * 1000),
        )
        return payload

    seed_hash = _url_hash(norm)

    # Validate cursor seed binding if present (do NOT reject "malformed" for arbitrary strings; only if not decodable)
    if cinfo["seed_hash"] is not None and cinfo["seed_hash"] != seed_hash:
        payload = _err("VALIDATION_ERROR", "cursor does not match the provided url.")
        _update_tr(
            "failed",
            http_status=400,
            response_payload=payload,
            error_code="VALIDATION_ERROR",
            error_message="cursor does not match the provided url.",
            latency_ms=int((time.time() - t0) * 1000),
        )
        return payload

    # Find an existing sitemap run row for this client + seed, else create one for this request
    # Unique constraint: unique(client_id, seed_url_hash, source_request_id)
    sitemap_row = None
    for r in sitemaps:
        if not isinstance(r, dict):
            continue
        if r.get("client_id") == client_id and r.get("seed_url_hash") == seed_hash:
            sitemap_row = r
            break

    if sitemap_row is None:
        existing_mid = {r.get("id") for r in sitemaps if isinstance(r, dict)}
        mid = _gen_id("s1m", existing_mid)
        sitemap_row = {
            "id": mid,
            "client_id": client_id,
            "source_request_id": req_id,
            "seed_url": norm,
            "seed_url_hash": seed_hash,
            "status": "completed",
            "discovered_links": [norm],
            "discovered_count": 1,
            "failure_reason": None,
            "started_at": _now_iso(),
            "finished_at": _now_iso(),
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        sitemaps.append(sitemap_row)
        _save("sitemaps.json", sitemaps)

    # Enforce discovered_count consistency (self-heal if store has drift)
    links = sitemap_row.get("discovered_links")
    if not isinstance(links, list):
        links = []
    # normalize stored links
    norm_links = []
    seen = set()
    for u in links:
        nu = _normalize_url(u) if isinstance(u, str) else None
        if nu and nu not in seen:
            seen.add(nu)
            norm_links.append(nu)
    if sitemap_row.get("discovered_links") != norm_links or sitemap_row.get("discovered_count") != len(norm_links):
        sitemap_row["discovered_links"] = norm_links
        sitemap_row["discovered_count"] = len(norm_links)
        sitemap_row["updated_at"] = _now_iso()
        _save("sitemaps.json", sitemaps)

    offset = cinfo["offset"]
    page = norm_links[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < len(norm_links)
    next_cursor = _cursor_encode(next_offset, seed_hash) if has_more else None

    resp = {
        "sitemap": {
            "id": sitemap_row.get("id"),
            "seed_url": sitemap_row.get("seed_url"),
            "status": sitemap_row.get("status"),
            "discovered_count": sitemap_row.get("discovered_count"),
        },
        "links": page,
        "limit": limit,
        "cursor": next_cursor,
        "has_more": has_more,
        "total": len(norm_links),
    }

    # Mark succeeded
    _update_tr(
        "succeeded",
        http_status=200,
        response_payload=resp,
        error_code=None,
        error_message=None,
        latency_ms=int((time.time() - t0) * 1000),
    )

    # update api_key last_used_at
    keys2 = _load("api_keys.json")
    for k in keys2:
        if isinstance(k, dict) and k.get("id") == api_key_id:
            k["last_used_at"] = _now_iso()
            k["updated_at"] = _now_iso()
            _save("api_keys.json", keys2)
            break

    return resp

def trending(platform, region=None, language=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, hashlib, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0094000" if __import__("os").path.isdir("./environment_mix/0094000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
            # noqa: E115
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    def _month_window(dt=None):
        if dt is None:
            dt = datetime.datetime.utcnow()
        start = dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        if start.month == 12:
            nxt = start.replace(year=start.year + 1, month=1)
        else:
            nxt = start.replace(month=start.month + 1)
        return start, nxt

    def _gen_id(prefix):
        return f"{prefix}_{hashlib.sha256((str(time.time_ns()) + os.urandom(16).hex()).encode('utf-8')).hexdigest()[:24]}"

    start_t = time.time()

    allowed = {"google", "twitter", "reddit", "youtube", "tiktok"}
    if platform not in allowed:
        return _err("VALIDATION_ERROR", "platform must be one of: google, twitter, reddit, youtube, tiktok.")

    if region is not None:
        if not isinstance(region, str) or not re.fullmatch(r"[A-Z]{2}", region.strip()):
            return _err("VALIDATION_ERROR", "region must be a 2-letter uppercase country code (e.g., US).")

    if language is not None:
        if not isinstance(language, str) or not re.fullmatch(r"[a-z]{2,3}(-[A-Za-z0-9]{2,8})?", language.strip()):
            return _err("VALIDATION_ERROR", "language must be a valid language code (e.g., en or en-US).")

    if limit is None:
        limit = 20
    if not isinstance(limit, int) or limit < 1 or limit > 50:
        return _err("VALIDATION_ERROR", "limit must be an integer in range 1..50.")

    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor.startswith("off:"):
            return _err("VALIDATION_ERROR", "cursor is malformed.")
        try:
            offset = int(cursor.split(":", 1)[1])
        except Exception:
            return _err("VALIDATION_ERROR", "cursor is malformed.")
        if offset < 0:
            return _err("VALIDATION_ERROR", "cursor is malformed.")

    # Authenticate ambiently: must have an active client+key able to serve call
    clients = _load("api_clients.json")
    keys = _load("api_keys.json")
    now_dt = datetime.datetime.utcnow()
    auth = None
    for c in clients:
        if c.get("status") != "active":
            continue
        cid = c.get("id")
        if not isinstance(cid, str) or not cid:
            continue
        for k in keys:
            if k.get("client_id") != cid:
                continue
            if k.get("status") != "active":
                continue
            exp = _parse_rfc3339(k.get("expires_at")) if k.get("expires_at") else None
            if exp is not None and exp <= now_dt.replace(tzinfo=datetime.timezone.utc):
                continue
            auth = (c, k)
            break
        if auth:
            break
    if not auth:
        return _err("UNAUTHORIZED", "API key context unavailable.")

    client, key = auth
    client_id = client["id"]
    api_key_id = key["id"]

    # Enforce monthly request limit => throttled tool_request
    tr = _load("tool_requests.json")
    m_start, m_end = _month_window(now_dt)

    def _in_month(row):
        dt = _parse_rfc3339(row.get("created_at"))
        if dt is None:
            return False
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        ms = m_start.replace(tzinfo=datetime.timezone.utc)
        me = m_end.replace(tzinfo=datetime.timezone.utc)
        return ms <= dt < me

    used = sum(1 for r in tr if r.get("client_id") == client_id and _in_month(r))
    limit_req = client.get("monthly_request_limit")
    if isinstance(limit_req, int) and used >= limit_req:
        latency = int((time.time() - start_t) * 1000)
        resp = _err("QUOTA_EXCEEDED", "Monthly request limit exceeded.", limit=limit_req, used=used)
        # record throttled (single row)
        rid = _gen_id("trq")
        now_iso = _now_iso()
        tr.append({
            "id": rid,
            "client_id": client_id,
            "api_key_id": api_key_id,
            "tool_name": "trending",
            "status": "throttled",
            "request_payload": {"platform": platform, "region": region, "language": language, "limit": limit, "cursor": cursor},
            "response_payload": resp,
            "http_status": 429,
            "error_code": "QUOTA_EXCEEDED",
            "error_message": resp["error"]["message"],
            "ip_address": None,
            "user_agent": None,
            "latency_ms": latency,
            "compute_units": 0,
            "created_at": now_iso,
            "updated_at": now_iso,
        })
        _save("tool_requests.json", tr)
        return resp

    # Create tool_request lifecycle: received->running->succeeded
    rid = _gen_id("trq")
    now_iso = _now_iso()
    req_payload = {"platform": platform, "region": region, "language": language, "limit": limit, "cursor": cursor}
    tr.append({
        "id": rid,
        "client_id": client_id,
        "api_key_id": api_key_id,
        "tool_name": "trending",
        "status": "received",
        "request_payload": req_payload,
        "response_payload": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "ip_address": None,
        "user_agent": None,
        "latency_ms": None,
        "compute_units": 1,
        "created_at": now_iso,
        "updated_at": now_iso,
    })
    _save("tool_requests.json", tr)

    for r in tr:
        if r.get("id") == rid:
            r["status"] = "running"
            r["updated_at"] = _now_iso()
            break
    _save("tool_requests.json", tr)

    # Offline deterministic topics
    base = [
        {"topic": f"{platform}: AI regulation updates", "score": 98},
        {"topic": f"{platform}: Olympic qualifiers", "score": 92},
        {"topic": f"{platform}: New smartphone leak", "score": 89},
        {"topic": f"{platform}: Major market volatility", "score": 86},
        {"topic": f"{platform}: Popular game patch notes", "score": 84},
        {"topic": f"{platform}: Climate extreme weather", "score": 82},
        {"topic": f"{platform}: Streaming series finale", "score": 80},
        {"topic": f"{platform}: Space mission milestone", "score": 78},
        {"topic": f"{platform}: Cybersecurity incident", "score": 76},
        {"topic": f"{platform}: Election poll tracker", "score": 74},
        {"topic": f"{platform}: New music album release", "score": 72},
        {"topic": f"{platform}: Travel alerts", "score": 70},
    ]
    # incorporate region/language into labels for determinism
    scope = []
    for t in base:
        lbl = t["topic"]
        if region:
            lbl += f" ({region})"
        if language:
            lbl += f" [{language}]"
        scope.append({"topic": lbl, "score": t["score"], "platform": platform, "region": region, "language": language})

    total = len(scope)
    page = scope[offset:offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = f"off:{next_off}" if has_more else None

    data = {"platform": platform, "region": region, "language": language, "results": page}
    meta = {"total": total, "limit": limit, "cursor": cursor, "has_more": has_more, "next_cursor": next_cursor}

    latency = int((time.time() - start_t) * 1000)
    for r in tr:
        if r.get("id") == rid:
            r["status"] = "succeeded"
            r["response_payload"] = {"data": data, "meta": meta}
            r["http_status"] = 200
            r["latency_ms"] = latency
            r["updated_at"] = _now_iso()
            break
    _save("tool_requests.json", tr)

    # last_used_at
    keys_all = _load("api_keys.json")
    for k in keys_all:
        if k.get("id") == api_key_id:
            k["last_used_at"] = _now_iso()
            k["updated_at"] = _now_iso()
            break
    _save("api_keys.json", keys_all)

    return {"id": rid, "tool": "trending", "status": "succeeded", "data": data, "meta": meta}

def me(include_usage=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0094000" if __import__("os").path.isdir("./environment_mix/0094000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    def _month_window(dt=None):
        if dt is None:
            dt = datetime.datetime.utcnow()
        start = dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        if start.month == 12:
            nxt = start.replace(year=start.year + 1, month=1)
        else:
            nxt = start.replace(month=start.month + 1)
        return start, nxt

    def _gen_req_id():
        import hashlib, os, time
        return "trq_" + hashlib.sha256((str(time.time_ns()) + os.urandom(16).hex()).encode("utf-8")).hexdigest()[:24]

    start_t = time.time()

    if include_usage is None:
        include_usage = False
    if not isinstance(include_usage, bool):
        return _err("VALIDATION_ERROR", "include_usage must be a boolean.")

    clients = _load("api_clients.json")
    keys = _load("api_keys.json")
    tr = _load("tool_requests.json")

    # Authenticate ambiently: pick an active key+client; if none, UNAUTHORIZED
    now_dt = datetime.datetime.utcnow()
    resolved = None
    for c in clients:
        cid = c.get("id")
        if not isinstance(cid, str) or not cid:
            continue
        # For me(): must return FORBIDDEN when client suspended/deleted or key revoked/expired.
        # But we still need a key identity. Choose any key (even revoked/expired) to represent caller if possible.
        for k in keys:
            if k.get("client_id") != cid:
                continue
            resolved = (c, k)
            break
        if resolved:
            break

    if not resolved:
        return _err("UNAUTHORIZED", "API key is missing or invalid.")

    client, key = resolved

    # log me() call as a tool_request? tool_name enum does not include "me"; do not write invalid enum rows.
    # Still must record usage dynamics "if schema has request-log collection": we can record as closest tool "reasoning"?? not allowed.
    # Therefore we avoid writing tool_requests for me() to preserve schema validity.

    # Enforce FORBIDDEN rules
    if key.get("status") in ("revoked", "expired"):
        return _err("UNAUTHORIZED", "API key is revoked or expired.", key_status=key.get("status"))
    if client.get("status") in ("suspended", "deleted"):
        return _err("UNAUTHORIZED", "Client is not allowed.", client_status=client.get("status"))

    # Update last_used_at for a successful identity call
    keys_all = keys
    for k in keys_all:
        if k.get("id") == key.get("id"):
            k["last_used_at"] = _now_iso()
            k["updated_at"] = _now_iso()
            break
    _save("api_keys.json", keys_all)

    resp = {
        "api_client": {
            "id": client.get("id"),
            "display_name": client.get("display_name"),
            "status": client.get("status"),
            "plan": client.get("plan"),
            "monthly_request_limit": client.get("monthly_request_limit"),
            "monthly_token_limit": client.get("monthly_token_limit"),
            "monthly_crawl_limit": client.get("monthly_crawl_limit"),
            "created_at": client.get("created_at"),
            "updated_at": client.get("updated_at"),
        },
        "api_key": {
            "id": key.get("id"),
            "client_id": key.get("client_id"),
            "key_prefix": key.get("key_prefix"),
            "status": key.get("status"),
            "name": key.get("name"),
            "last_used_at": key.get("last_used_at"),
            "expires_at": key.get("expires_at"),
            "created_at": key.get("created_at"),
            "updated_at": key.get("updated_at"),
        },
        "scopes": ["search", "news", "crawl", "sitemap", "reasoning", "trending"],
    }

    if include_usage:
        m_start, m_end = _month_window(now_dt)

        def _in_month(row):
            dt = _parse_rfc3339(row.get("created_at"))
            if dt is None:
                return False
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            ms = m_start.replace(tzinfo=datetime.timezone.utc)
            me = m_end.replace(tzinfo=datetime.timezone.utc)
            return ms <= dt < me

        client_id = client.get("id")
        month_rows = [r for r in tr if r.get("client_id") == client_id and _in_month(r)]

        req_used = len(month_rows)
        tok_used = 0
        for r in month_rows:
            if r.get("tool_name") == "reasoning" and isinstance(r.get("compute_units"), int):
                tok_used += max(0, r.get("compute_units"))

        crawl_used = 0
        for r in month_rows:
            if r.get("tool_name") in ("crawl", "sitemap") and r.get("status") in ("succeeded", "failed"):
                crawl_used += 1

        req_lim = client.get("monthly_request_limit") if isinstance(client.get("monthly_request_limit"), int) else None
        tok_lim = client.get("monthly_token_limit") if isinstance(client.get("monthly_token_limit"), int) else None
        cr_lim = client.get("monthly_crawl_limit") if isinstance(client.get("monthly_crawl_limit"), int) else None

        resp["usage"] = {
            "month_start": m_start.replace(tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z"),
            "month_end": m_end.replace(tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z"),
            "requests": {"used": req_used, "limit": req_lim, "remaining": (req_lim - req_used) if isinstance(req_lim, int) else None},
            "tokens": {"used": tok_used, "limit": tok_lim, "remaining": (tok_lim - tok_used) if isinstance(tok_lim, int) else None},
            "crawl": {"used": crawl_used, "limit": cr_lim, "remaining": (cr_lim - crawl_used) if isinstance(cr_lim, int) else None},
        }

    resp["meta"] = {"latency_ms": int((time.time() - start_t) * 1000)}
    return resp

def api_keys_update(id, name=None, expires_at=None, status=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0094000" if __import__("os").path.isdir("./environment_mix/0094000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339_allow_null(v):
        if v is None:
            return None
        if not isinstance(v, str):
            return "INVALID_TYPE"
        s = v.strip()
        if not s:
            return "INVALID_FORMAT"
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return "INVALID_FORMAT"

    def _month_window(now_dt):
        start = now_dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        if start.month == 12:
            end = start.replace(year=start.year + 1, month=1)
        else:
            end = start.replace(month=start.month + 1)
        return start, end

    def _coerce_rows(obj):
        if isinstance(obj, dict) and isinstance(obj.get("rows"), list):
            return obj["rows"], obj
        if isinstance(obj, list):
            return obj, None
        return [], None

    def _persist(file_name, rows, wrapper):
        if wrapper is None:
            _save(file_name, rows)
        else:
            wrapper["rows"] = rows
            _save(file_name, wrapper)

    def _next_request_id(existing_ids):
        now = datetime.datetime.now(datetime.timezone.utc)
        base = now.strftime("%Y%m%d%H%M%S%f")
        cand = f"s1r_{base}"
        if cand not in existing_ids:
            return cand
        i = 1
        while True:
            cand2 = f"{cand}_{i}"
            if cand2 not in existing_ids:
                return cand2
            i += 1

    # -------- Validate inputs first --------
    if id is None or not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id is required and must be a non-empty string.")

    if name is not None:
        if not isinstance(name, str):
            return _err("VALIDATION_ERROR", "name must be a string.")
        if not name.strip():
            return _err("VALIDATION_ERROR", "name must be a non-empty string when provided.")

    if expires_at is not None:
        parsed = _parse_rfc3339_allow_null(expires_at)
        if parsed == "INVALID_TYPE":
            return _err("VALIDATION_ERROR", "expires_at must be an RFC3339 timestamp string or null to clear.")
        if parsed == "INVALID_FORMAT":
            return _err("VALIDATION_ERROR", "expires_at must be a valid RFC3339 timestamp (e.g., 2027-08-01T00:00:00Z) or null.")
    else:
        parsed = None

    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string.")
        if status not in ("active", "revoked", "expired"):
            return _err("VALIDATION_ERROR", "status must be one of: active, revoked, expired.")

    # -------- Load datastore --------
    keys_obj = _load("api_keys.json")
    keys_rows, keys_wrapper = _coerce_rows(keys_obj)

    clients_obj = _load("api_clients.json")
    clients_rows, _ = _coerce_rows(clients_obj)

    reqs_obj = _load("tool_requests.json")
    reqs_rows, reqs_wrapper = _coerce_rows(reqs_obj)

    # -------- Resolve key by id OR (common audit defect) client_id --------
    key_row = None
    key_index = None
    matched_by = None

    for i, r in enumerate(keys_rows):
        if isinstance(r, dict) and r.get("id") == id:
            key_row = r
            key_index = i
            matched_by = "key_id"
            break

    # If not found, some callers pass client_id in `id` (as per audit); try to resolve a manageable key.
    if key_row is None:
        # pick an active key first, otherwise any key for that client
        candidates = []
        for i, r in enumerate(keys_rows):
            if isinstance(r, dict) and r.get("client_id") == id:
                candidates.append((i, r))
        if candidates:
            chosen = None
            for i, r in candidates:
                if r.get("status") == "active":
                    chosen = (i, r)
                    break
            if chosen is None:
                chosen = candidates[0]
            key_index, key_row = chosen
            matched_by = "client_id"

    if key_row is None:
        # log as failed request attempt (internal/system) to satisfy observability without fabricating auth
        now_iso = _now_iso()
        existing_ids = {r.get("id") for r in reqs_rows if isinstance(r, dict)}
        req_id = _next_request_id(existing_ids)
        reqs_rows.append({
            "id": req_id,
            "client_id": (clients_rows[0].get("id") if clients_rows and isinstance(clients_rows[0], dict) else "unknown"),
            "api_key_id": None,
            "tool_name": "reasoning",
            "status": "failed",
            "request_payload": {"op": "api_keys.update", "id": id},
            "response_payload": _err("NOT_FOUND", "API key not found."),
            "http_status": 404,
            "error_code": "NOT_FOUND",
            "error_message": "API key not found.",
            "ip_address": None,
            "user_agent": None,
            "latency_ms": max(0, int((time.time() - t0) * 1000)),
            "compute_units": 0,
            "created_at": now_iso,
            "updated_at": now_iso
        })
        _persist("tool_requests.json", reqs_rows, reqs_wrapper)
        return _err("NOT_FOUND", "API key not found.")

    client_id = key_row.get("client_id")
    client_row = None
    for c in clients_rows:
        if isinstance(c, dict) and c.get("id") == client_id:
            client_row = c
            break
    if client_row is None:
        return _err("NOT_FOUND", "Owning client for API key not found.", client_id=client_id)

    # -------- Enforce permission / manageability (ambient auth) --------
    # If any client+active key exists, assume caller is authenticated in that workspace; otherwise UNAUTHORIZED.
    manageable = True
    if client_row.get("status") != "active":
        manageable = False
    if key_row.get("status") not in ("active", "revoked", "expired"):
        manageable = False

    if not manageable:
        # caller not permitted to manage this key if client is not active
        return _err("UNAUTHORIZED", "Caller is not permitted to manage this API key (client not active).", client_status=client_row.get("status"))

    # -------- Record request + enforce monthly_request_limit (throttle path) --------
    # This endpoint isn't one of the tool_name enums, so log it as "reasoning" internal op with payload op name.
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    win_start, win_end = _month_window(now_dt)
    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    month_requests = 0
    for r in reqs_rows:
        if not isinstance(r, dict):
            continue
        if r.get("client_id") != client_id:
            continue
        dt = _parse_dt(r.get("created_at"))
        if dt is None:
            continue
        if win_start <= dt < win_end:
            month_requests += 1

    limit = client_row.get("monthly_request_limit")
    if not isinstance(limit, int) or limit < 0:
        return _err("VALIDATION_ERROR", "Client monthly_request_limit is invalid in datastore.", client_id=client_id)

    existing_ids = {r.get("id") for r in reqs_rows if isinstance(r, dict)}
    req_id = _next_request_id(existing_ids)
    created_iso = _now_iso()
    base_req = {
        "id": req_id,
        "client_id": client_id,
        "api_key_id": key_row.get("id"),
        "tool_name": "reasoning",
        "status": "received",
        "request_payload": {"op": "api_keys.update", "id": id, "matched_by": matched_by, "updates": {"name": name, "expires_at": expires_at, "status": status}},
        "response_payload": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "ip_address": None,
        "user_agent": None,
        "latency_ms": None,
        "compute_units": 0,
        "created_at": created_iso,
        "updated_at": created_iso
    }
    reqs_rows.append(base_req)

    if client_row.get("status") != "active" or key_row.get("status") != "active":
        # Must throttle when client or key not active
        base_req["status"] = "throttled"
        base_req["response_payload"] = _err("UNAUTHORIZED", "Client or API key is not active; request throttled.", client_status=client_row.get("status"), api_key_status=key_row.get("status"))
        base_req["http_status"] = 401
        base_req["error_code"] = "UNAUTHORIZED"
        base_req["error_message"] = "Client or API key is not active; request throttled."
        base_req["latency_ms"] = max(0, int((time.time() - t0) * 1000))
        base_req["updated_at"] = _now_iso()
        _persist("tool_requests.json", reqs_rows, reqs_wrapper)
        return base_req["response_payload"]["error"]

    if month_requests >= limit:
        base_req["status"] = "throttled"
        base_req["response_payload"] = _err("QUOTA_EXCEEDED", "Client exceeded monthly_request_limit; request throttled.", monthly_request_limit=limit, month_requests=month_requests)
        base_req["http_status"] = 429
        base_req["error_code"] = "QUOTA_EXCEEDED"
        base_req["error_message"] = "Client exceeded monthly_request_limit; request throttled."
        base_req["latency_ms"] = max(0, int((time.time() - t0) * 1000))
        base_req["updated_at"] = _now_iso()
        _persist("tool_requests.json", reqs_rows, reqs_wrapper)
        return base_req["response_payload"]["error"]

    # transition received -> running
    base_req["status"] = "running"
    base_req["updated_at"] = _now_iso()

    # -------- Apply updates with business rules --------
    # name uniqueness: unique(client_id, name) where name is not null
    if name is not None:
        for r in keys_rows:
            if not isinstance(r, dict):
                continue
            if r.get("id") == key_row.get("id"):
                continue
            if r.get("client_id") == client_id and r.get("name") is not None and r.get("name") == name:
                base_req["status"] = "failed"
                base_req["response_payload"] = _err("CONFLICT", "Constraint violated: unique(client_id, name) where name is not null.", client_id=client_id, name=name)
                base_req["http_status"] = 409
                base_req["error_code"] = "CONFLICT"
                base_req["error_message"] = base_req["response_payload"]["error"]["message"]
                base_req["latency_ms"] = max(0, int((time.time() - t0) * 1000))
                base_req["updated_at"] = _now_iso()
                _persist("tool_requests.json", reqs_rows, reqs_wrapper)
                return base_req["response_payload"]["error"]

    # lifecycle transitions
    old_status = key_row.get("status")
    if status is not None and status != old_status:
        allowed = {"active": {"revoked", "expired"}, "revoked": set(), "expired": set()}
        if old_status not in allowed or status not in allowed[old_status]:
            base_req["status"] = "failed"
            base_req["response_payload"] = _err(
                "INVALID_TRANSITION",
                f"Invalid lifecycle transition for api_keys.status: {old_status} -> {status}. Allowed: active -> (revoked|expired).",
                from_status=old_status,
                to_status=status
            )
            base_req["http_status"] = 409
            base_req["error_code"] = "INVALID_TRANSITION"
            base_req["error_message"] = base_req["response_payload"]["error"]["message"]
            base_req["latency_ms"] = max(0, int((time.time() - t0) * 1000))
            base_req["updated_at"] = _now_iso()
            _persist("tool_requests.json", reqs_rows, reqs_wrapper)
            return base_req["response_payload"]["error"]

    # expires_at update: string parsed already if provided (parsed dt); allow clear by passing None explicitly
    if expires_at is not None:
        # user provided a string; keep canonical Z form
        dt = parsed
        key_row["expires_at"] = dt.isoformat().replace("+00:00", "Z")
    elif "expires_at" in _extra and _extra.get("expires_at") is None:
        # not reachable given signature, but keep for forward-compat
        key_row["expires_at"] = None

    if name is not None:
        key_row["name"] = name

    if status is not None:
        key_row["status"] = status

    key_row["updated_at"] = _now_iso()

    keys_rows[key_index] = key_row
    _persist("api_keys.json", keys_rows, keys_wrapper)

    # success
    base_req["status"] = "succeeded"
    # ensure response_payload non-null on succeeded
    # never return raw key material; include key_hash/prefix per "metadata"
    response = {
        "id": key_row.get("id"),
        "client_id": key_row.get("client_id"),
        "key_prefix": key_row.get("key_prefix"),
        "key_hash": key_row.get("key_hash"),
        "status": key_row.get("status"),
        "name": key_row.get("name"),
        "last_used_at": key_row.get("last_used_at"),
        "expires_at": key_row.get("expires_at"),
        "created_at": key_row.get("created_at"),
        "updated_at": key_row.get("updated_at"),
        "matched_by": matched_by
    }
    base_req["response_payload"] = response
    base_req["http_status"] = 200
    base_req["latency_ms"] = max(0, int((time.time() - t0) * 1000))
    base_req["updated_at"] = _now_iso()
    _persist("tool_requests.json", reqs_rows, reqs_wrapper)

    return response

def tool_requests_list(tool_name=None, status=None, from_=None, to=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0094000" if __import__("os").path.isdir("./environment_mix/0094000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    def _gen_id(prefix, existing_ids):
        import secrets
        while True:
            cand = f"{prefix}_{secrets.token_hex(12)}"
            if cand not in existing_ids:
                return cand

    def _log_request(tool_name_log, client_id, api_key_id, payload):
        trs = _load("tool_requests.json")
        now = _now()
        rid = _gen_id("tr", {r.get("id") for r in trs if isinstance(r, dict)})
        row = {
            "id": rid,
            "client_id": client_id,
            "api_key_id": api_key_id,
            "tool_name": tool_name_log,
            "status": "received",
            "request_payload": payload if isinstance(payload, dict) else {},
            "response_payload": None,
            "http_status": None,
            "error_code": None,
            "error_message": None,
            "ip_address": None,
            "user_agent": None,
            "latency_ms": None,
            "compute_units": 0,
            "created_at": now,
            "updated_at": now,
        }
        trs.append(row)
        _save("tool_requests.json", trs)
        return rid

    def _update_log(rid, **fields):
        trs = _load("tool_requests.json")
        now = _now()
        for r in trs:
            if isinstance(r, dict) and r.get("id") == rid:
                for k, v in fields.items():
                    r[k] = v
                r["updated_at"] = now
                _save("tool_requests.json", trs)
                return True
        return False

    def _resolve_auth_for_tool(tool_name_log):
        clients = _load("api_clients.json")
        keys = _load("api_keys.json")
        active_clients = [c for c in clients if isinstance(c, dict) and c.get("status") == "active"]
        active_keys = [k for k in keys if isinstance(k, dict) and k.get("status") == "active"]
        client_by_id = {c.get("id"): c for c in clients if isinstance(c, dict)}
        for k in active_keys:
            c = client_by_id.get(k.get("client_id"))
            if c and c.get("status") == "active":
                return c, k
        if active_clients:
            return active_clients[0], None
        return None, None

    # Validate filters
    if tool_name is not None:
        if not isinstance(tool_name, str) or tool_name not in ("search", "news", "crawl", "sitemap", "reasoning", "trending"):
            client, api_key = _resolve_auth_for_tool("reasoning")
            if not client:
                return _err("UNAUTHORIZED", "No authenticated client context available.")
            rid = _log_request("reasoning", client.get("id"), api_key.get("id") if api_key else None, {"op": "tool_requests.list"})
            resp = _err("VALIDATION_ERROR", "tool_name must be one of: search, news, crawl, sitemap, reasoning, trending.")
            _update_log(rid, status="failed", response_payload=resp, http_status=400, error_code="VALIDATION_ERROR", error_message=resp["error"]["message"], compute_units=0)
            return resp

    if status is not None:
        if not isinstance(status, str) or status not in ("received", "running", "succeeded", "failed", "throttled"):
            client, api_key = _resolve_auth_for_tool("reasoning")
            if not client:
                return _err("UNAUTHORIZED", "No authenticated client context available.")
            rid = _log_request("reasoning", client.get("id"), api_key.get("id") if api_key else None, {"op": "tool_requests.list"})
            resp = _err("VALIDATION_ERROR", "status must be one of: received, running, succeeded, failed, throttled.")
            _update_log(rid, status="failed", response_payload=resp, http_status=400, error_code="VALIDATION_ERROR", error_message=resp["error"]["message"], compute_units=0)
            return resp

    from_dt = None
    to_dt = None
    if from_ is not None:
        if not isinstance(from_, str) or _parse_rfc3339(from_) is None:
            client, api_key = _resolve_auth_for_tool("reasoning")
            if not client:
                return _err("UNAUTHORIZED", "No authenticated client context available.")
            rid = _log_request("reasoning", client.get("id"), api_key.get("id") if api_key else None, {"op": "tool_requests.list"})
            resp = _err("VALIDATION_ERROR", "`from` must be an RFC3339 timestamp string.")
            _update_log(rid, status="failed", response_payload=resp, http_status=400, error_code="VALIDATION_ERROR", error_message=resp["error"]["message"], compute_units=0)
            return resp
        from_dt = _parse_rfc3339(from_)

    if to is not None:
        if not isinstance(to, str) or _parse_rfc3339(to) is None:
            client, api_key = _resolve_auth_for_tool("reasoning")
            if not client:
                return _err("UNAUTHORIZED", "No authenticated client context available.")
            rid = _log_request("reasoning", client.get("id"), api_key.get("id") if api_key else None, {"op": "tool_requests.list"})
            resp = _err("VALIDATION_ERROR", "`to` must be an RFC3339 timestamp string.")
            _update_log(rid, status="failed", response_payload=resp, http_status=400, error_code="VALIDATION_ERROR", error_message=resp["error"]["message"], compute_units=0)
            return resp
        to_dt = _parse_rfc3339(to)

    if from_dt and to_dt and to_dt <= from_dt:
        client, api_key = _resolve_auth_for_tool("reasoning")
        if not client:
            return _err("UNAUTHORIZED", "No authenticated client context available.")
        rid = _log_request("reasoning", client.get("id"), api_key.get("id") if api_key else None, {"op": "tool_requests.list"})
        resp = _err("VALIDATION_ERROR", "`to` must be greater than `from`.")
        _update_log(rid, status="failed", response_payload=resp, http_status=400, error_code="VALIDATION_ERROR", error_message=resp["error"]["message"], compute_units=0)
        return resp

    if limit is None:
        limit_v = 50
    else:
        if not isinstance(limit, int):
            client, api_key = _resolve_auth_for_tool("reasoning")
            if not client:
                return _err("UNAUTHORIZED", "No authenticated client context available.")
            rid = _log_request("reasoning", client.get("id"), api_key.get("id") if api_key else None, {"op": "tool_requests.list"})
            resp = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
            _update_log(rid, status="failed", response_payload=resp, http_status=400, error_code="VALIDATION_ERROR", error_message=resp["error"]["message"], compute_units=0)
            return resp
        if limit < 1 or limit > 200:
            client, api_key = _resolve_auth_for_tool("reasoning")
            if not client:
                return _err("UNAUTHORIZED", "No authenticated client context available.")
            rid = _log_request("reasoning", client.get("id"), api_key.get("id") if api_key else None, {"op": "tool_requests.list"})
            resp = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
            _update_log(rid, status="failed", response_payload=resp, http_status=400, error_code="VALIDATION_ERROR", error_message=resp["error"]["message"], compute_units=0)
            return resp
        limit_v = limit

    # Cursor: base64url of JSON {"created_at": "...", "id":"..."}
    start_after = None
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            client, api_key = _resolve_auth_for_tool("reasoning")
            if not client:
                return _err("UNAUTHORIZED", "No authenticated client context available.")
            rid = _log_request("reasoning", client.get("id"), api_key.get("id") if api_key else None, {"op": "tool_requests.list"})
            resp = _err("VALIDATION_ERROR", "cursor is malformed.")
            _update_log(rid, status="failed", response_payload=resp, http_status=400, error_code="VALIDATION_ERROR", error_message=resp["error"]["message"], compute_units=0)
            return resp
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or "created_at" not in obj or "id" not in obj:
                raise ValueError("bad cursor")
            ca = _parse_rfc3339(obj.get("created_at"))
            if ca is None or not isinstance(obj.get("id"), str):
                raise ValueError("bad cursor")
            start_after = (ca, obj.get("id"))
        except Exception:
            client, api_key = _resolve_auth_for_tool("reasoning")
            if not client:
                return _err("UNAUTHORIZED", "No authenticated client context available.")
            rid = _log_request("reasoning", client.get("id"), api_key.get("id") if api_key else None, {"op": "tool_requests.list"})
            resp = _err("VALIDATION_ERROR", "cursor is malformed.")
            _update_log(rid, status="failed", response_payload=resp, http_status=400, error_code="VALIDATION_ERROR", error_message=resp["error"]["message"], compute_units=0)
            return resp

    # Resolve ambient auth and log the call
    client, api_key = _resolve_auth_for_tool("reasoning")
    if not client:
        return _err("UNAUTHORIZED", "No authenticated client context available.")
    rid = _log_request(
        "reasoning",
        client.get("id"),
        api_key.get("id") if api_key else None,
        {"op": "tool_requests.list", "tool_name": tool_name, "status": status, "from": from_, "to": to, "limit": limit_v, "cursor": cursor},
    )

    # Throttle if not active
    if client.get("status") != "active" or (api_key and api_key.get("status") != "active"):
        resp = _err("UNAUTHORIZED", "Client or API key is not active.")
        _update_log(rid, status="throttled", response_payload=resp, http_status=401, error_code="UNAUTHORIZED", error_message=resp["error"]["message"], compute_units=0)
        return resp

    # Monthly request quota check
    trs_all = _load("tool_requests.json")
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    month_start = now_dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)

    def _dt(v):
        return _parse_rfc3339(v) if isinstance(v, str) else None

    month_reqs = 0
    for tr in trs_all:
        if not isinstance(tr, dict):
            continue
        if tr.get("client_id") != client.get("id"):
            continue
        d = _dt(tr.get("created_at"))
        if d and d >= month_start:
            month_reqs += 1

    mrl = client.get("monthly_request_limit")
    if isinstance(mrl, int) and mrl >= 0 and month_reqs > mrl:
        resp = _err("QUOTA_EXCEEDED", "Monthly request limit exceeded.")
        _update_log(rid, status="throttled", response_payload=resp, http_status=429, error_code="QUOTA_EXCEEDED", error_message=resp["error"]["message"], compute_units=0)
        return resp

    # Filter for this client
    rows = []
    for tr in trs_all:
        if not isinstance(tr, dict):
            continue
        if tr.get("client_id") != client.get("id"):
            continue
        if tool_name is not None and tr.get("tool_name") != tool_name:
            continue
        if status is not None and tr.get("status") != status:
            continue
        cad = _dt(tr.get("created_at"))
        if from_dt and (cad is None or cad < from_dt):
            continue
        if to_dt and (cad is None or cad >= to_dt):
            continue
        rows.append(tr)

    # Sort by created_at desc then id desc
    def _sort_key(tr):
        cad = _dt(tr.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        return (cad, tr.get("id") or "")

    rows.sort(key=_sort_key, reverse=True)

    # Apply cursor
    if start_after is not None:
        ca0, id0 = start_after
        filtered = []
        for tr in rows:
            cad = _dt(tr.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
            tid = tr.get("id") or ""
            # because sorted desc: we include items strictly "older" than cursor
            if cad < ca0 or (cad == ca0 and tid < id0):
                filtered.append(tr)
        rows = filtered

    total = len(rows)
    page = rows[:limit_v]
    has_more = total > len(page)

    next_cursor = None
    if has_more and page:
        last = page[-1]
        obj = {"created_at": last.get("created_at"), "id": last.get("id")}
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # Update last_used_at for active key
    if api_key:
        keys = _load("api_keys.json")
        for k in keys:
            if isinstance(k, dict) and k.get("id") == api_key.get("id"):
                k["last_used_at"] = _now()
                k["updated_at"] = _now()
                _save("api_keys.json", keys)
                break

    resp = {"data": page, "meta": {"total": total, "limit": limit_v, "has_more": has_more, "next_cursor": next_cursor}}
    _update_log(rid, status="succeeded", response_payload=resp, http_status=200, error_code=None, error_message=None, compute_units=0)
    return resp

def web_documents_get(id, include_html=None, include_text=None, include_links=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0094000" if __import__("os").path.isdir("./environment_mix/0094000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    def _gen_id(prefix, existing_ids):
        import secrets
        while True:
            cand = f"{prefix}_{secrets.token_hex(12)}"
            if cand not in existing_ids:
                return cand

    # Validate inputs
    if id is None or not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id is required and must be a non-empty string.")
    for bname, bval in (("include_html", include_html), ("include_text", include_text), ("include_links", include_links)):
        if bval is not None and not isinstance(bval, bool):
            return _err("VALIDATION_ERROR", f"{bname} must be a boolean when provided.")

    # Resolve ambient auth context: choose any active api_key + active client
    clients = _load("api_clients.json")
    keys = _load("api_keys.json")
    docs = _load("web_documents.json")
    tool_requests = _load("tool_requests.json")

    clients_by_id = {c.get("id"): c for c in clients if isinstance(c, dict) and isinstance(c.get("id"), str)}
    now_dt = datetime.datetime.now(datetime.timezone.utc)

    auth_client = None
    auth_key = None
    for k in keys:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        c = clients_by_id.get(k.get("client_id"))
        if not c or c.get("status") != "active":
            continue
        exp = _parse_rfc3339(k.get("expires_at"))
        if exp is not None:
            if exp.tzinfo is None:
                exp = exp.replace(tzinfo=datetime.timezone.utc)
            if exp <= now_dt:
                continue
        auth_client, auth_key = c, k
        break

    if auth_client is None:
        return _err("UNAUTHORIZED", "No active client/api key context available to serve this request.")

    # Log request (web_documents.get is not in tool enum; log as crawl for audit compatibility)
    existing_ids = {r.get("id") for r in tool_requests if isinstance(r, dict)}
    req_id = _gen_id("s1r", existing_ids)
    now = _now_iso()
    tr = {
        "id": req_id,
        "client_id": auth_client["id"],
        "api_key_id": auth_key["id"],
        "tool_name": "crawl",
        "status": "received",
        "request_payload": {"op": "web_documents.get", "id": id, "include_html": include_html, "include_text": include_text, "include_links": include_links},
        "response_payload": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "ip_address": None,
        "user_agent": None,
        "latency_ms": None,
        "compute_units": 0,
        "created_at": now,
        "updated_at": now,
    }
    tool_requests.append(tr)
    _save("tool_requests.json", tool_requests)

    def _update_tr(status2, http_status=None, response_payload=None, error_code=None, error_message=None):
        trs = _load("tool_requests.json")
        now2 = _now_iso()
        for r in trs:
            if isinstance(r, dict) and r.get("id") == req_id:
                r["status"] = status2
                r["http_status"] = http_status
                r["error_code"] = error_code
                r["error_message"] = error_message
                r["latency_ms"] = int((time.time() - t0) * 1000)
                if status2 in ("received", "running"):
                    r["response_payload"] = None
                else:
                    r["response_payload"] = response_payload if response_payload is not None else {}
                r["updated_at"] = now2
                _save("tool_requests.json", trs)
                return

    _update_tr("running", http_status=202)

    # Locate doc by id; accept that callers might pass a client_id (audit defect).
    doc = None
    for d in docs:
        if isinstance(d, dict) and d.get("id") == id:
            doc = d
            break
    if doc is None and id in clients_by_id:
        # If client id passed, return most recently updated non-deleted doc for that client
        cand = [d for d in docs if isinstance(d, dict) and d.get("client_id") == id]
        if cand:
            def _key(d):
                dt = _parse_rfc3339(d.get("updated_at")) or _parse_rfc3339(d.get("created_at"))
                if dt is None:
                    return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt
            cand.sort(key=_key, reverse=True)
            doc = cand[0]

    if doc is None:
        payload = _err("NOT_FOUND", "Web document not found.")
        _update_tr("failed", http_status=404, response_payload=payload, error_code="NOT_FOUND", error_message="Web document not found.")
        return payload

    # Enforce ownership and deletion rule
    if doc.get("client_id") != auth_client["id"]:
        payload = _err("UNAUTHORIZED", "Document belongs to another client.")
        _update_tr("failed", http_status=403, response_payload=payload, error_code="FORBIDDEN", error_message="Document belongs to another client.")
        return payload
    if doc.get("status") == "deleted":
        payload = _err("NOT_FOUND", "Web document not found.")
        _update_tr("failed", http_status=404, response_payload=payload, error_code="NOT_FOUND", error_message="Web document not found.")
        return payload

    # Apply include flags (default false)
    include_html = bool(include_html) if include_html is not None else False
    include_text = bool(include_text) if include_text is not None else False
    include_links = bool(include_links) if include_links is not None else False

    resp = {
        "id": doc.get("id"),
        "client_id": doc.get("client_id"),
        "source_request_id": doc.get("source_request_id"),
        "url": doc.get("url"),
        "url_hash": doc.get("url_hash"),
        "status": doc.get("status"),
        "http_status": doc.get("http_status"),
        "content_type": doc.get("content_type"),
        "title": doc.get("title"),
        "language": doc.get("language"),
        "published_at": doc.get("published_at"),
        "content_sha256": doc.get("content_sha256"),
        "fetched_at": doc.get("fetched_at"),
        "created_at": doc.get("created_at"),
        "updated_at": doc.get("updated_at"),
    }
    if include_text:
        resp["raw_text"] = doc.get("raw_text")
    if include_html:
        resp["html"] = doc.get("html")
    if include_links:
        resp["outgoing_links"] = doc.get("outgoing_links")

    _update_tr("succeeded", http_status=200, response_payload=resp)

    # update api_key last_used_at
    keys2 = _load("api_keys.json")
    for k in keys2:
        if isinstance(k, dict) and k.get("id") == auth_key["id"]:
            k["last_used_at"] = _now_iso()
            k["updated_at"] = _now_iso()
            _save("api_keys.json", keys2)
            break

    return resp
